    let mut score = 0.0;

    // Penalize the current bin if it's almost full
    if bin_residual < item_size {
        score += (bin_capacity - bin_residual) as f64;
    }

    // Reward bins that are already partially filled
    if bin_residual > bin_capacity / 2 {
        score -= (bin_residual - bin_capacity / 2) as f64 * 0.5;
    }

    // Penalize creating new bins
    if open_bins_count == 1 && item_size <= next_item_size {
        score += 100.0;
    }

    // Reward using existing bins efficiently
    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64 - 1.0) * 10.0;
    }

    // Penalize creating bins with too much empty space
    if post_residual < bin_capacity / 4 {
        score += (bin_capacity - post_residual) as f64 * 2.0;
    }

    score
