pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Enhanced Horizontal Swarm Crossover Logic
    if bin_residual < mean_residual / 5.0 {
        score += (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 1.3;
    } else if bin_residual > mean_residual / 2.0 {
        score -= (bin_residual as f64 / bin_capacity as f64).powi(2) * 1.0;
    }

    // Adjusted logic for fitting bins
    if fitting_bins_count > 0 && next_item_size > 0 {
        let fit_ratio = next_item_size as f64 / bin_capacity as f64;
        score += fit_ratio.powi(3) * (1.5 + fit_ratio);
    } else {
        score -= 0.75;
    }

    // Improved residual handling
    if post_residual >= item_size {
        score += (item_size as f64 / bin_capacity as f64).powi(2) * 1.3;
    } else {
        score -= 0.8 * post_residual as f64 / mean_residual;
    }

    // Progress penalty with non-linear decay
    let progress = step_index as f64 / total_items as f64;
    score -= (progress.powi(2) + 1.5 * progress) * 3.0;

    // Penalty for open bins when post-residual is zero
    if open_bins_count > 1 && post_residual == 0 {
        score -= 1.3 * bin_capacity as f64 / total_items as f64;
    }

    // Encouragement for low post-residuals
    if post_residual < mean_residual / 2.5 {
        score += 0.7 + 0.1 * post_residual as f64 / mean_residual;
    }

    // Additional heuristics with adaptive thresholds
    let capacity_ratio = bin_capacity - bin_residual;
    if capacity_ratio <= next_item_size {
        score -= 1.6;
    } else if capacity_ratio <= next_item_size * 1.5 {
        score -= 1.2;
    }

    score
}

