pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Prioritize using bins with higher residual space
    score += (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Penalize creating new bins if it leads to significant empty space
    if open_bins_count > 1 {
        score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    // Reward bins that can fit the next item efficiently
    if fitting_bins_count > 0 && next_item_size > 0 {
        score += (next_item_size as f64 / bin_capacity as f64).powi(2);
    }

    // Penalize bins with low residual space but high open bins count
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln();

    // Reward the use of mean residual for better utilization
    score += mean_residual;

    // Penalize empty bins if there are too many open bins
    if open_bins_count > 1 && post_residual == 0 {
        score -= 1.0;
    }

    // Favor bins that can fit the current item without exceeding capacity
    if post_residual >= item_size {
        score += (item_size as f64 / bin_capacity as f64).powi(2);
    } else {
        score -= 1.0;
    }

    // Penalize high step index to encourage earlier bin utilization
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Combined residual and capacity ratio
    score += (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * ((post_residual as f64) as f64).sqrt();

    // Penalize open bins count if greater than 1
    if open_bins_count > 1 {
        score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    // Reward for fitting bins and next item size
    if fitting_bins_count > 0 && next_item_size > 0 {
        score += ((next_item_size as f64 / bin_capacity as f64).powi(2)) * 1.5;
    }

    // Penalize bin residual based on open bins count and natural logarithm
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln() * 0.75;

    // Add mean residual to score
    score += mean_residual;

    // Penalize if open bins count is greater than 1 and post residual is zero
    if open_bins_count > 1 && post_residual == 0 {
        score -= 1.0;
    }

    // Reward for item size fitting into the bin or penalty otherwise
    if post_residual >= item_size {
        score += ((item_size as f64 / bin_capacity as f64).powi(2)) * 1.25;
    } else {
        score -= 0.5;
    }

    // Progress factor to penalize based on step index
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 3.0;

    // Reward if post residual is below half of mean residual
    if post_residual < mean_residual / 2.0 {
        score += 1.0;
    }

    score
}
